-- BUKLOD MAIN Bible V4 reviewed bilingual alias expansion; no client/OTA/schema change.
-- Append only; historical score increases and bounded, uniquely keyed credits.
do $fix$
declare entry record; q record; i int; g jsonb; merged jsonb; a record; r record;
 old_units int; new_units int; delta int; score int; review jsonb; desired int; bonus int; credited uuid; total_credit int; v_rule record;
begin
 for entry in select key,value from jsonb_each($aliases${"v4_h_n01":[["pamamahagi ng ikabubuhay","pang araw araw na pamamahagi ng pagkain","pangangailangan ng byuda","pagkain para sa mga biyuda","daily distribution of food","daily ministration","daily food distribution"],["pangangaral ng salita ng diyos","ministeryo ng salita","prayer and preaching the word","ministry of the word","dapat ipagpatuloy ng mga apostol ang pangangaral at pananalangin"]],"v4_h_n02":[["readiness of mind","all readiness of mind","with all readiness of mind","received the word with all readiness of mind","received the message with great eagerness","received the word eagerly","eagerly received the message","open minded","open mindedness","bukas ang isipan","wiling wili sa pakikinig","wiling wili sa pakikinig at unawain ang mensahe","buong pananabik na pagtanggap","buong pananabik nilang tinanggap ang mensahe","masigasig na tumanggap ng saluta ng diyos","masigasig na tumanggap ng salita ng diyos","may pananabik sila na nakinig sa paliwanag ni pablo","wiling wili sila sa pakikinig sa mga paliwanag ni pablo","tinanggap ang salita nang buong pananabik","masigasig na nakinig"],["searching scripture","searching scriptures","searching the scripture","searching the scriptures","searched the scriptures","searched the scriptures daily","search the scriptures daily","searching the scriptures daily","examined the scriptures every day","daily study of scripture","araw araw na pagsasaliksalik","araw araw na pagsisiyasat sa kasulatan","araw araw nilang sinasaliksik ang kasulatan upang tiyakin kung totoo ang itinuro ni pablo","araw araw nilang sinasaliksik ang kasulatan upang tiyakin kung totoo ang mga itinuro","araw araw na nagsiyasat ng kasulatan upang tiyakin kung totoo ang kanilang narinig","sinasaliksik nila araw araw ang nga kasulatan uoang tinganan kung totoo ang sinasabi niya","sinasaliksik nila ang kasulatan upang tingnan kung totoo nga ang sinasabi niya","sinusuri ang kasulatan araw araw","pagsasaliksik sa kasulatan"]],"v4_h_n03":[["meat offered to idols","things offered to idols","pollutions of idols"],["abstain from blood"],["things strangled","things from strangled"],["fornication","things from fornication","abstain from fornication"]],"v4_h_n04":[["hinugasan ang kanilang sugat","hinugasan ang mga latay","hinugasan ang mga sugat nina pablo at silas","inalagaan at hinugasan niya ang mga sugat nina pablo at silas","1. hinugasan ang mga sugat nina pablo at silas (o nilinis ang kanilang mga sugat)","hinugasan ang mga sugat nila pablo at nagpabautismo","washed their stripes"],["nagpabautismo siya kasama ang buong sambahayan niya","baptized with his household","he and his household were baptized"],["2. nagpakain kina pablo at silas sa kanyang tahanan (o dinala sila sa bahay at pinakain)","isinama niya sa kanyang tahanan at ipinaghanda ng pagkain","served them food","fed paul and silas"],["nagtanong kung paano maligtas","what must i do to be saved","dinala niya sila sa labas at tinanong kung paano siya maliligtas"]],"v4_h_n05":[["bukid","mga bukid","lupain","sakahan","1. mga bukid / lupa (o mga sakahan/lupain)"],["ubasan","vineyard"],["oliveyards","olive gardens","puno ng olibo"],["house","mga bahay","2. mga bahay, ubasan, at mga puno ng olibo (o mga bahay at ubasan)"]],"v4_h_n06":[["pulse","legumes","gulay lamang ang kakainin","kumain lamang ng gulay bilang pagkain","pagkain ng mga gulay lamang sa halip na ang pagkaing galing sa hapag ng hari","gulay at tubig lang ang ibigay sa kanila","gulay at tubig lang ang pagkain","kumain lamang ng mga gulay at uminom ng tubig sa loob ng sampung araw"],["tubig lamang ang iinumin","uminom lamang ng tubig","water to drink","pag inom ng tubig sa halip na alak","pag inom ng tubig sa halip na alak, at pagkatapos ay suriin at ihambing ang kanilang mukha sa mga kabataang kumakain ng"]],"v4_h_n07":[["nilagyan ng benda ang sugat","binendahan ang sugat","hinugasan ang sugat at binendahan","binalutan niya ng benda ang mga sugat ng lal