ind","received the word with all readiness of mind","received the message with great eagerness","eager reception","bukas ang isipan","bukas na pakikinig","buong pananabik na pagtanggap","buong pananabik nilang tinanggap ang mensahe","wiling wili sa pakikinig"],["searching scripture","searching scriptures","searching the scripture","searching the scriptures","searched the scriptures","searching the scriptures daily","examined the scriptures every day","daily examination of scriptures","araw araw na pagsasaliksalik","araw araw na pagsisiyasat sa kasulatan","pagsusuri ng kasulatan","pagsasaliksik sa kasulatan"]],"v4_m_n03":[["daylight","light created"],["vault","sky","dome","firmament of heaven"]],"v4_m_n04":[["timotheus","timoteo"],["silvanus"]],"v4_m_n05":[["command stones to become bread","make these stones bread"],["cast yourself down from the temple","jump from the pinnacle of the temple"],["bow down and worship satan","worship the devil for the kingdoms"]],"v4_m_n06":[["dumating ang iyong kaharian","thy kingdom come"],["matupad ang iyong kalooban","thy will be done"],["give us this day our daily bread","ibigay mo sa amin ngayon ang aming kakanin sa araw araw","ibigay mo sa amin ang aming pagkain sa araw araw"],["forgive us our trespasses","forgive us our debts","at ipatawad mo sa amin ang aming mga utang, gaya naman namin na nagpatawad sa mga may utang sa amin"],["do not lead us into temptation","lead us not into temptation"],["deliver us from the evil one","iligtas kami sa masama"],["banal ang iyong pangalan","sambahin ang ngalan mo","hallowed be thy name","hallowed be your name"]]}$aliases$::jsonb) loop
  select * into strict q from private.buklod_bible_v4_questions where id=entry.key and kind='enumeration' and reviewed and active for update;
  if jsonb_array_length(entry.value)<>jsonb_array_length(q.answer_spec->'groups') and not (q.id='v4_m_n06' and jsonb_array_length(q.answer_spec->'groups') in (6,7) and jsonb_array_length(entry.value)=7) then raise exception 'Unexpected answer groups: %',q.id; end if;
  merged:='[]'::jsonb;
  for i in 0..jsonb_array_length(entry.value)-1 loop
   g:=coalesce(q.answer_spec->'groups'->i,'[]'::jsonb);
   select g||coalesce(jsonb_agg(x.value order by x.value),'[]'::jsonb) into g
   from (select distinct value from jsonb_array_elements_text(entry.value->i)) x
   where not exists(select 1 from jsonb_array_elements_text(g) y where private.buklod_bible_v4_enum_normalize(y.value)=private.buklod_bible_v4_enum_normalize(x.value));
   merged:=merged||jsonb_build_array(g);
  end loop;
  update private.buklod_bible_v4_questions set answer_spec=jsonb_set(q.answer_spec,'{groups}',merged) where id=q.id;
 end loop;
 -- Exact reported case and order independence; reject unrelated concepts.
 if (select count(*) from private.buklod_bible_v4_questions b cross join lateral jsonb_array_elements(b.answer_spec->'groups') gg where b.id in ('v4_h_n02','v4_m_n02') and exists(select 1 from jsonb_array_elements_text(gg.value) t where private.buklod_bible_v4_enum_normalize(t.value) in ('readiness of mind','searching scripture')))<>4 then raise exception 'Berea aliases not installed';end if;
 for a in select * from private.buklod_bible_v4_attempts where state='completed' and jsonb_typeof(review_items)='array' and score_units between 0 and 10 for update loop
  delta:=0; review:=a.review_items;
  for r in select item,ordinal from jsonb_array_elements(a.review_items) with ordinality j(item,ordinal) where item->>'kind'='enumeration' and (item->>'earned_units')::int between 0 and 1 loop
   select * into q from private.buklod_bible_v4_questions where id=r.item->>'id' and kind='enumeration' and reviewed and active;
   if not found or not ($aliases${"v4_h_n01":[["pamamahagi ng ikabubuhay","pang araw araw na pamamahagi ng pagkain","pangangailangan ng byuda","pagkain para sa mga biyuda","daily distribution of food","daily ministration","daily food distribution"],["pangangaral ng salita ng diyos","ministeryo ng salita","prayer and preaching the word","ministry of the word","dapat ipagpatuloy ng mga apostol ang pangangaral at pananalangin"]],"v4_h_n02":[["readiness of mind","all readiness of mind","with all readiness of mind","received the word with all readiness of mind","received the message with great eagerness","received the word eagerly","eagerly received the message","open minded","open mindedness","bukas ang isipan","wiling wili sa pakikinig","wiling wili sa pakikinig at unawain ang mensahe","buong pananabik na pagtanggap","buong pananabik nilang tinanggap ang mensahe","masigasig na tumanggap ng saluta ng diyos","masigasig na tumanggap ng salita ng diyos","may pananabik sila na nakinig sa paliwanag ni pablo","wiling wili sila sa pakikinig sa mga paliwanag ni pablo","tinanggap ang salita nang buong pananabik","masigasig na nakinig"],["searching scripture","searching scriptures","searching the scripture","searching the scriptures","searched the scriptures","searched the scriptures daily","search the scriptures daily","searching the scriptures daily","examined the scriptures every day","daily study of scripture","araw araw na pagsasaliksalik","araw araw na pagsisiyasat sa kasulatan","araw araw nilang sinasaliksik ang kasulatan upang tiyakin kung totoo ang itinuro ni pablo","araw araw nilang sinasaliksik ang kasulatan upang tiyakin kung totoo ang mga itinuro","araw araw na nagsiyasat ng kasulatan upang tiyakin kung totoo ang kanilang narinig","sinasaliksik nila araw araw ang nga kasulatan uoang tinganan kung totoo ang sinasabi niya","sinasaliksik nila ang kasulatan upang tingnan kung totoo nga ang sinasabi niya","sinusuri ang kasulatan araw araw","pagsasaliksik sa kasulatan"]],"v4_h_n03":[["meat offered to idols","things offered to idols","pollutions of idols"],["abstain from blood"],["things strangled","things from strangled"],["fornication","things from fornication","abstain from fornication"]],"v4_h_n04":[["hinugasan ang kanilang sugat","hinugasan ang mga latay","hinugasan ang mga sugat nina pablo at silas","inalagaan at hinugasan niya ang mga sugat nina pablo at silas","1. hinugasan ang mga sugat nina pablo at silas (o nilinis ang kanilang mga sugat)","hinugasan ang mga sugat nila pablo at nagpabautismo","washed their stripes"],["nagpabautismo siya kasama ang buong sambahayan niya","baptized with his household","he and his household were baptized"],["2. nagpakain kina pablo at silas sa kanyang tahanan (o dinala sila sa bahay at pinakain)","isinama niya sa kanyang tahanan at ipinaghanda ng pagkain","served them food","fed paul and silas"],["nagtanong kung paano maligtas","what must i do to be saved","dinala niya sila sa labas at tinanong kung paano siya maliligtas"]],"v4_h_n05":[["bukid","mga bukid","lupain","sakahan","1. mga bukid / lupa (o mga sakahan/lupain)"],["ubasan","vineyard"],["oliveyards","olive gardens","puno ng olibo"],["house","mga bahay","2. mga bahay, ubasan, at mga puno ng olibo (o mga bahay at ubasan)"]],"v4_h_n06":[["pulse","legumes","gulay lamang ang kakainin","kumain lamang ng gulay bilang pagkain","pagkain ng mga gulay lamang sa halip na ang pagkaing galing sa hapag ng hari","gulay at tubig lang ang ibigay sa kanila","gulay at tubig lang ang pagkain","kumain lamang ng mga gulay at uminom ng tubig sa loob ng sampung araw"],["tubig lamang ang iinumin","uminom lamang ng tubig","water to drink","pag inom ng tubig sa halip na alak","pag inom ng tubig sa halip na alak, at pagkatapos ay suriin at ihambing ang kanilang mukha sa mga kabataang kumakain ng"]],"v4_h_n07":[["nilagyan ng benda ang sugat","binendahan ang sugat","hinugasan ang sugat at binendahan","binalutan niya ng benda ang mga sugat ng lalaki at nilagyan ng langis at alak","tinalian niya ang mga sugat ng lalaki at binuhusan ng langis at alak","bound up his wounds","dressed the wounds"],["dinala sa bahay tuluyan","dinala ito sa bahay pagamutan","isinakay niya ito sa kaniyang hayop, dinala sa bahay panuluyan at inalagaan","isinakay niya ang lalaki sa kanyang hayop at dinala sa bahay panuluyan upang maalagaan","isinakay sa kanyang sariling hayop at dinala sa bahay tuluyan at inalagaan","took him to an inn"],["binayaran ang bahay panuluyan","binayaran ang gastos sa pagpapagamot","binayaran ang mga nagastos sa pagamutan","binigyan ng salaping pilak ang may ari ng panuluyan at inihabilin ang lalaki","paid for his care","gave two denarii to the innkeeper"],["binuhusan ng langis at alak ang sugat","nilagyan niya ng langis at alak ang mga sugat ng lalaki","poured in oil and wine","poured oil and wine"]],"v4_h_n08":[["pagkagutom","nagutom","nagugutom","pinakain","pagkain para sa mga nagugutom","pagkagutom – binigyan ng pagkain ang mga nagugutom","pagkagutom – pagbibigay ng pagkain","pagkagutom, pagbibigay ng pagkain sa mga nagugutom"],["pagkauhaw","nauuhaw","pinainom","pagkauhaw – binigyan ng tubig o inumin ang mga nauuhaw","pagkauhaw – pagbibigay ng maiinom","pagkauhaw, pagbibigay ng maiinom sa mga nauuhaw"],["pinatuloy","stranger welcomed","welcomed a stranger"],["walang masuot","walang maisuot","dinamitan","damit para sa mga walang maisuot","clothed the naked"],["nagkasakit at dinalaw","visited the sick"],["nabilanggo at pinuntahan","visited prisoners","visited the prisoner"]],"v4_m_n01":[["bound up his wounds","nilagyan ng benda ang sugat","binendahan ang sugat","bandaged the wounds"],["dinala sa bahay tuluyan","brought him to an inn","brought to an inn"],["paid the innkeeper","gave two denarii to the innkeeper","binayaran ang bahay panuluyan"],["binuhusan ng langis at alak ang sugat","poured in oil and wine","oil and wine"]],"v4_m_n02":[["readiness of mind","all readiness of mind","with all readiness of mind","received the word with all readiness of mind","received the message with great eagerness","eager reception","bukas ang isipan","bukas na pakikinig","buong pananabik na pagtanggap","buong pananabik nilang tinanggap ang mensahe","wiling wili sa pakikinig"],["searching scripture","searching scriptures","searching the scripture","searching the scriptures","searched the scriptures","searching the scriptures daily","examined the scriptures every day","daily examination of scriptures","araw araw na pagsasaliksalik","araw araw na pagsisiyasat sa kasulatan","pagsusuri ng kasulatan","pagsasaliksik sa kasulatan"]],"v4_m_n03":[["daylight","light created"],["vault","sky","dome","firmament of heaven"]],"v4_m_n04":[["timotheus","timoteo"],["silvanus"]],"v4_m_n05":[["command stones to become bread","make these stones bread"],["cast yourself down from the temple","jump from the pinnacle of the temple"],["bow down and worship satan","worship the devil for the kingdoms"]],"v4_m_n06":[["dumating ang iyong kaharian","thy kingdom come"],["matupad ang iyong kalooban","thy will be done"],["give us this day our daily bread","ibigay mo sa amin ngayon ang aming kakanin sa araw araw","ibigay mo sa amin ang aming pagkain sa araw araw"],["forgive us our trespasses","forgive us our debts","at ipatawad mo sa amin ang aming mga utang, gaya naman namin na nagpatawad sa mga may utang sa amin"],["do not lead us into temptation","lead us not into temptation"],["deliver us from the evil one","iligtas kami sa masama"],["banal ang iyong pangalan","sambahin ang ngalan mo","hallowed be thy name","hallowed be your name"]]}$aliases$::jsonb ? q.id) or jsonb_typeof(a.submitted_answers->q.id) is distinct from 'array' then continue;end if;
   if jsonb_array_length(a.submitted_answers->q.id)<>2 or exists(select 1 from jsonb_array_elements(a.submitted_answers->q.id) j where jsonb_typeof(j.value)<>'string') then continue;end if;
   if private.buklod_bible_v4_enum_normalize(a.submitted_answers->q.id->>0)=private.buklod_bible_v4_enum_normalize(a.submitted_answers->q.id->>1) then continue;end if;
   old_units:=(r.item->>'earned_units')::int;
   if q.id='v4_h_n03' then new_units:=private.buklod_bible_v4_acts15_units(a.submitted_answers->q.id,q.answer_spec);
   else
    select least(2,count(*)) into new_units from jsonb_array_elements(q.answer_spec->'groups') gg where exists(select 1 from jsonb_array_elements_text(a.submitted_answers->q.id) va(answer) cross join lateral private.buklod_bible_v4_enum_parts(va.answer) candidate(normalized) join lateral jsonb_array_elements_text(gg.value) accepted(answer) on candidate.normalized=private.buklod_bible_v4_enum_normalize(accepted.answer));
   end if;
   if new_units<=old_units then continue;end if;
   delta:=delta+new_units-old_units;
   review:=jsonb_set(review,array[(r.ordinal-1)::text],jsonb_set(jsonb_set(r.item,'{earned_units}',to_jsonb(new_units)),'{correct_answer}',q.answer_spec));
  end loop;
  if delta=0 then continue;end if;
  score:=a.score_units+delta;
  if score>10 then raise exception 'Historical score overflow';end if;
  bonus:=0;credited:=null;
  select coalesce(sum(l.points),0) into total_credit from public.buklod_points_ledger l where l.user_id=a.user_id and l.direction='credit' and l.activity_type='bible_quiz_'||a.difficulty and (l.source_key='bible_quiz:r3:'||a.local_date::text or (l.source_key like 'bible_quiz:v4:%' and right(l.source_key,36)=a.id::text));
  if a.ledger_id is not null and total_credit=coalesce(a.points_awarded,0) and exists(select 1 from public.buklod_points_ledger l where l.id=a.ledger_id and l.user_id=a.user_id and l.direction='credit' and l.source_key='bible_quiz:r3:'||a.local_date::text and l.activity_type='bible_quiz_'||a.difficulty) then
   select base_points,max_points_per_event,is_active into v_rule from public.buklod_point_rules where activity_type='bible_quiz_'||a.difficulty;
   if found and v_rule.is_active then
    desired:=least(private.buklod_bible_v4_points(a.difficulty,score),v_rule.base_points,coalesce(v_rule.max_points_per_event,12),12);
    bonus:=greatest(desired-total_credit,0);
    if bonus>0 then
     insert into public.buklod_points_ledger(user_id,direction,points,activity_type,source_key,description,awarded_by)
     values(a.user_id,'credit',bonus,'bible_quiz_'||a.difficulty,'bible_quiz:v4:alias-grade-fix:20261126:'||a.id::text,'Verified Bible V4 equivalent answer correction',a.user_id)
     on conflict(user_id,source_key) do nothing returning id into credited;
     if credited is null then bonus:=0;end if;
    end if;
   end if;
  end if;
  update private.buklod_bible_v4_attempts set review_items=review,score_units=score,points_awarded=coalesce(a.points_awarded,0)+bonus where id=a.id;
  insert into public.notifications(user_id,title,body,kind,data)
  values(a.user_id,'Bible Quiz: inayos ang iyong marka','Naitama ang iyong Bible Quiz score sa '||score||'/10. '||case when bonus>0 then '+'||bonus||' BP ang naidagdag.' else 'Walang karagdagang BP na na-credit.' end,'bible_quiz_result',jsonb_build_object('attempt_id',a.id,'score_units',score,'correction_units',delta,'points_added',bonus,'route','/faith/bible-quiz','correction_version','20261126_aliases'));
 end loop;
end;
$fix$;
